/// undo-toast: Delete with undo
private struct UndoToastExample0: View {
    @State private var toasts = MonarchToastCenter()
    @State private var notes = ["Agenda for Monday", "Questions for the review", "Ideas for the next sprint"]

    private func delete(_ note: String) {
        guard let index = notes.firstIndex(of: note) else { return }
        notes.remove(at: index)
        let window: TimeInterval = 8
        let commit = Task {
            try? await Task.sleep(for: .seconds(window * toasts.durationScale))
            guard !Task.isCancelled else { return }
            // Delete on the server here.
        }
        toasts.show("Note deleted", message: note, actionTitle: "Undo", duration: window) {
            commit.cancel()
            notes.insert(note, at: min(index, notes.count))
            toasts.show("Restored", tone: .success, duration: 4)
        }
    }

    var body: some View {
        Group {
            VStack(alignment: .leading) {
                ForEach(notes, id: \.self) { note in
                    HStack {
                        Text(note)
                        Spacer()
                        MonarchButton("Delete \(note)", systemImage: "trash", variant: .ghost, isIconOnly: true) {
                            delete(note)
                        }
                    }
                }
            }
            .frame(maxWidth: 360, minHeight: 200, alignment: .topLeading)
            .monarchToastHost(toasts)
        }
        .task {
            guard PreviewMode.presented else { return }
            try? await Task.sleep(for: .milliseconds(400))
            delete(notes[0])
        }
    }
}
